const triplesSumToZero = (l) => {
  if (l.length < 3) return false;
  l.sort((a, b) => a - b);
  for (let i = 0; i < l.length - 2; i++) {
    let left = i + 1;
    let right = l.length - 1;
    while (left < right) {
      const sum = l[i] + l[left] + l[right];
      if (sum === 0) {
        return true;
      } else if (sum < 0) {
        left++;
      } else {
        right--;
      }
    }
  }
  return false;
};

